", "tools/contact_note.py": """"Add a note to a contact from its plain text: POST /crm/v3/objects/contacts/notes wants {id, note_b64}."""
import json

NOTES = 'https://api.hubapi.com/crm/v3/objects/contacts/notes'


def add_contact_note(ctx, args):
    encoded = ctx.call_tool('base64_encode', {'text': str(args.get('text', ''))})
    if encoded.is_error:
        return encoded.output
    body = json.dumps({'id': args.get('contact_id'), 'note_b64': encoded.output})
    return ctx.call_tool('api_fetch', {'method': 'POST', 'url': NOTES, 'body': body}).output
